import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { has, isQuestion, stateOf, t } from '../util';
/**
 * One request per question page for the side column (related articles and
 * the "solved it" numbers), kept per discussion so moving between the
 * question and other pages never asks twice.
 */
const cache = new Map();
const pending = new Map();
function load(discussion) {
  const id = discussion.id();
  if (cache.has(id)) return cache.get(id);
  if (!pending.has(id)) {
    pending.set(id, app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/helpdesk/discussions/${id}`,
      errorHandler: () => {}
    }).then(side => {
      cache.set(id, side);
      m.redraw();
    }).catch(() => {
      cache.set(id, {
        kb: [],
        feedback: null
      });
    }));
  }
  return null;
}

/** Scroll to an element of the question, below the header. */
function jump(selector) {
  const el = document.querySelector(selector);
  if (el) el.scrollIntoView({
    behavior: 'smooth',
    block: 'start'
  });
}

/** "On this question": the question, its accepted answer, the rest. */
export class Contents extends Component {
  view() {
    const discussion = this.attrs.discussion;
    const question = isQuestion(discussion);
    const solved = stateOf(discussion) === 'solved';
    const links = [[t('toc.question'), () => window.scrollTo({
      top: 0,
      behavior: 'smooth'
    })]];
    if (solved) links.push([t('toc.accepted'), () => jump(question ? '.AnswersPost--accepted' : '.helpdesk-accepted')]);
    if (question) {
      links.push([t('toc.answers'), () => jump('.Answers-bar')]);
    } else if ((discussion.commentCount() || 0) > 1) {
      links.push([t('toc.replies'), () => app.current.get('stream')?.goToNumber?.(2)]);
    }
    return m("nav", {
      className: "HelpDeskToc",
      "aria-labelledby": "helpdesk-toc"
    }, m("h2", {
      className: "HelpDeskSide-heading",
      id: "helpdesk-toc"
    }, t('toc.heading')), m("ul", null, links.map(([label, go]) => m("li", null, m("button", {
      type: "button",
      className: "HelpDeskToc-link",
      onclick: go
    }, label)))));
  }
}

/** "Did this solve it for you?", under a solved question only. */
export class Solved extends Component {
  saving = false;
  view() {
    // Only an accepted answer is asked about; nothing is fetched otherwise.
    if (stateOf(this.attrs.discussion) !== 'solved') return null;
    const side = load(this.attrs.discussion);
    const feedback = side?.feedback;
    if (!feedback) return null;
    const answer = helpful => {
      if (!app.session.user) {
        app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
        return;
      }
      this.saving = true;
      app.request({
        method: 'POST',
        url: `${app.forum.attribute('apiUrl')}/helpdesk/discussions/${this.attrs.discussion.id()}/feedback`,
        body: {
          helpful
        }
      }).then(next => {
        cache.set(this.attrs.discussion.id(), {
          kb: side.kb,
          feedback: next.feedback
        });
      }).finally(() => {
        this.saving = false;
        m.redraw();
      });
    };
    return m("section", {
      className: "HelpDeskSolved",
      "aria-labelledby": "helpdesk-solved"
    }, m("h2", {
      className: "HelpDeskSolved-question",
      id: "helpdesk-solved"
    }, t('solved.question')), feedback.mine === null ? m("div", {
      className: "HelpDeskSolved-buttons"
    }, m(Button, {
      className: "Button HelpDeskSolved-button",
      disabled: this.saving,
      onclick: () => answer(true)
    }, t('solved.yes')), m(Button, {
      className: "Button HelpDeskSolved-button",
      disabled: this.saving,
      onclick: () => answer(false)
    }, t('solved.no'))) : m("p", {
      className: "HelpDeskSolved-thanks",
      "aria-live": "polite"
    }, feedback.mine ? t('solved.thanks_yes') : t('solved.thanks_no'), ' ', m("button", {
      type: "button",
      className: "HelpDeskSolved-undo",
      disabled: this.saving,
      onclick: () => answer(null)
    }, t('solved.undo'))), m("p", {
      className: "HelpDeskSolved-count"
    }, t('solved.count', {
      count: feedback.yes
    })));
  }
}

/** "From the knowledge base": up to three articles about the same thing. */
export class Guides extends Component {
  view() {
    if (!has('ernestdefoe-knowledge-base')) return null;
    const articles = load(this.attrs.discussion)?.kb;
    if (!articles?.length) return null;
    const href = slug => app.routes['kb.article'] ? app.route('kb.article', {
      slug
    }) : app.forum.attribute('baseUrl') + '/kb/' + slug;
    return m("section", {
      className: "HelpDeskGuides",
      "aria-labelledby": "helpdesk-guides"
    }, m("h2", {
      className: "HelpDeskSide-heading",
      id: "helpdesk-guides"
    }, t('kb.heading')), m("ul", null, articles.map(article => m("li", null, m(Link, {
      className: "HelpDeskGuides-link",
      href: href(article.slug)
    }, m(Icon, {
      name: "far fa-file-alt"
    }), m("span", null, article.title))))));
  }
}
flarum.reg.add('ernestdefoe-helpdesk', 'forum/components/QuestionAside', { Contents: Contents,Solved: Solved,Guides: Guides, });