import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import { data, fmt, t, topics as forumTopics } from '../util';
import { openSearch } from '../search';

/**
 * The search hero at the top of the home page.
 *
 * The box is a real input, and pressing Enter (or a popular chip) opens
 * core's own search with the words already in it: discussions, posts,
 * members and any source another extension adds (Knowledge Base's
 * articles, say), searched by whatever driver the forum runs (core's,
 * Typesense, Manticore, OpenSearch). Help Desk never searches anything
 * itself.
 */
export default class Hero extends Component {
  value = '';
  oninit(vnode) {
    super.oninit(vnode);
    this.value = app.search.state.getValue() || '';
  }
  view() {
    const title = app.forum.attribute('helpdeskHeroTitle') || t('hero.title');
    const popular = app.forum.attribute('helpdeskPopular') || [];
    const submit = q => openSearch(q);
    return m("header", {
      className: "HelpDeskHero Hero"
    }, m("div", {
      className: "container"
    }, m("h1", {
      className: "HelpDeskHero-title"
    }, title), m("p", {
      className: "HelpDeskHero-text"
    }, this.text()), m("form", {
      className: "HelpDeskHero-search",
      role: "search",
      onsubmit: e => {
        e.preventDefault();
        submit(this.value);
      }
    }, m("button", {
      type: "submit",
      className: "HelpDeskHero-go",
      "aria-label": extractText(t('hero.label'))
    }, m(Icon, {
      name: "fas fa-search"
    })), m("input", {
      id: "helpdesk-search",
      className: "HelpDeskHero-input",
      type: "search",
      enterkeyhint: "search",
      autocomplete: "off",
      "aria-label": extractText(t('hero.label')),
      placeholder: extractText(t('hero.placeholder')),
      value: this.value,
      oninput: e => {
        this.value = e.target.value;
      }
    }), m("kbd", {
      className: "HelpDeskHero-key",
      title: extractText(t('hero.shortcut')),
      "aria-hidden": "true"
    }, "/")), popular.length > 0 && m("div", {
      className: "HelpDeskHero-popular"
    }, m("span", {
      className: "HelpDeskHero-popularLabel"
    }, t('hero.popular')), popular.map(q => m("button", {
      type: "button",
      className: "HelpDeskHero-chip",
      onclick: () => submit(q)
    }, q)))));
  }
  text() {
    const custom = app.forum.attribute('helpdeskHeroText');
    if (custom) return custom;
    const {
      mode,
      topics,
      guides
    } = data();
    // Top-level topics only: a question in a child tag is in its parent too.
    const answered = mode === 'none' ? 0 : forumTopics().reduce((sum, tag) => sum + (topics[tag.id()]?.[1] || 0), 0);
    const parts = [];
    if (answered) parts.push(extractText(t('hero.answered', {
      count: answered,
      formatted: fmt(answered)
    })));
    if (guides) parts.push(extractText(t('hero.guides', {
      count: guides
    })));
    if (!parts.length) return t('hero.text_plain');
    return t('hero.text', {
      things: parts.length === 2 ? extractText(t('hero.both', {
        first: parts[0],
        second: parts[1]
      })) : parts[0]
    });
  }
}
flarum.reg.add('ernestdefoe-helpdesk', 'forum/components/Hero', Hero);